import React, { useState } from 'react';
import CTreeTransfer from '..';
import type { TreeTransferDataType } from '../interface';
import { LoadType } from '../interface';
import { getInitTreeData, getTablesDataByKey, getDataBaseDataByInstanceIDInExpand, getSearchData } from './mockData';

export default () => {
  const [data, setData] = useState<TreeTransferDataType[]>(getInitTreeData().data);
  const [values, setValue] = useState<TreeTransferDataType[]>([]);
  const [loading] = useState(false);

  const loadMore = async (nodeData: TreeTransferDataType, pageSize = 10): Promise<TreeTransferDataType> => {
    if (nodeData?.type === 'instance') {
      if (nodeData.key === '0') {
        const dbData = await getDataBaseDataByInstanceIDInExpand({
          id: nodeData?.key || 0,
          dbNum: 1000,
          initCount: nodeData.children?.length || 0,
        });
        return {
          ...nodeData,
          nodeExtra: '数据过多(>5000)，请使用搜索过滤',
          children: dbData.data,
        };
      }

      const dbData = await getDataBaseDataByInstanceIDInExpand({
        id: nodeData?.key || 0,
        dbNum: pageSize,
        initCount: nodeData.children?.length || 0,
      });
      return {
        ...nodeData,
        children: dbData.data,
      };
    }

    const tableData = await getTablesDataByKey({
      tableNum: 10,
      instanceId: '0',
      dbId: nodeData.key,
      initCount: nodeData?.children?.length,
    });
    return {
      ...nodeData,
      children: tableData.data,
    };
  };

  const onSearch = async (searchStr: string) => {
    const res = await getSearchData(searchStr);
    setData(res);
    // setLoading(false);
  };

  return (
    <>
      <CTreeTransfer
        hasLoadMore={false}
        onExpand={loadMore}
        loadType={LoadType.remoteExpand}
        treeData={data}
        targetTreeData={values}
        loading={loading}
        onChange={setValue}
        onSearch={onSearch}
      />
    </>
  );
};

import React, { useState } from 'react';
import CTreeTransfer from '..';
import type { TreeTransferDataType } from '../interface';
import { getDataBaseDataByInstanceID, getInitTreeData, getSearchData, getTablesDataByKey } from './mockData';
import { cloneDeep, set } from 'lodash-es';

const findItem = (data: TreeTransferDataType[], key: string | number) => {
  return data.find(item => item.key === key);
};
const findItemByPath = (
  pathParentKeys: (string | number)[],
  transferTree: TreeTransferDataType[],
): TreeTransferDataType | undefined => {
  const item = findItem(transferTree, pathParentKeys[0]);
  if (pathParentKeys.length === 1 || !item) {
    return item;
  }
  return findItemByPath(pathParentKeys.slice(1), item.children || []);
};

export default () => {
  const [data, setData] = useState<TreeTransferDataType[]>(getInitTreeData().data);
  const [values, setValue] = useState<TreeTransferDataType[]>([]);
  const [loading, setLoading] = useState(false);

  const loadMore = async (parentKeys: (string | number)[], oldData: any[], pageSize = 10) => {
    const cloneTree = cloneDeep(oldData);
    const nodeData = findItemByPath(parentKeys, cloneTree);

    if (nodeData?.type === 'instance') {
      const dbData = await getDataBaseDataByInstanceID({
        id: nodeData?.key || 0,
        dbNum: pageSize,
        initCount: nodeData.children?.length || 0,
      });
      set(nodeData, 'children', [...(nodeData?.children || []), ...dbData.data]);
      set(nodeData, 'hasMore', dbData.hasMore);
      return cloneTree;
    }

    const tableData = await getTablesDataByKey({
      tableNum: 10,
      instanceId: parentKeys[0],
      dbId: parentKeys[1],
      initCount: nodeData?.children?.length,
    });
    if (nodeData) {
      set(nodeData, 'children', [...(nodeData?.children || []), ...tableData.data]);
      set(nodeData, 'hasMore', tableData.hasMore);
    }
    return cloneTree;
  };

  const onSearch = async (searchStr: string, type: 'source' | 'target') => {
    if (type === 'source') {
      setLoading(true);
      const res = await getSearchData(searchStr);
      setData(res);
      setLoading(false);
    }
  };

  const onSourceLoadMore = async (parentKeys: string[]) => {
    const newData = (await loadMore(parentKeys, data)) || [];
    setData(newData);
  };
  const onTargetLoadMore = async (parentKeys: string[]) => {
    const newData = (await loadMore(parentKeys, values)) || [];
    setValue(newData);
  };

  return (
    <>
      <CTreeTransfer
        hasLoadMore={true}
        treeData={data}
        targetTreeData={values}
        loading={loading}
        onChange={setValue}
        onSourceLoadMore={onSourceLoadMore}
        onTargetLoadMore={onTargetLoadMore}
        onSearch={onSearch}
        isExpandTarget={true}
        isAutoExpandSource={true}
        removeChildConfirmInfo={{
          isShowConfirm: true,
          title: '是否确认移除',
          content: '移除后将取消父节点全选状态',
        }}
      />
    </>
  );
};

