import React, { useState } from 'react';
import CTreeTransfer from '..';
import type { TreeTransferDataType } from '../interface';
import { getInitDbTreeData, getSearchData, getTablesDataByKey } from './mockData';
import { cloneDeep, set } from 'lodash-es';
import { Input } from '@cloud-materials/common';
import { IconSearch } from '@arco-design/iconbox-react-ve-o-design';
import type { NodeProps } from '@arco-design/web-react/es/Tree/interface';
import CEllipsis from '../../CEllipsis';

const findItem = (data: TreeTransferDataType[], key: string | number) => {
  return data.find(item => item.key === key);
};
const findItemByPath = (
  pathParentKeys: (string | number)[],
  transferTree: TreeTransferDataType[],
): TreeTransferDataType | undefined => {
  const item = findItem(transferTree, pathParentKeys[0]);
  if (pathParentKeys.length === 1 || !item) {
    return item;
  }
  return findItemByPath(pathParentKeys.slice(1), item.children || []);
};

const renderTargetHeader = () => {
  return (
    <div style={{ paddingRight: '12px' }}>
      <Input style={{ margin: '8px 0' }} placeholder="搜索数据库" prefix={<IconSearch />} size="small" />
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          height: '28px',
          borderBottom: '1px solid #e5e8ef',
          margin: '2px 0 8px',
        }}
      >
        <div style={{ marginRight: '97px' }}>已选择的实例库表</div>
        <div style={{ marginRight: '122px' }}>数据库新名</div>
      </div>
    </div>
  );
};

const renderTargetItem = ({
  item,
  onInputChange,
}: {
  item: NodeProps;
  onInputChange: (key: string, newValue: string) => void;
}) => {
  const { dataRef } = item;
  return (
    <div style={{ display: 'flex', alignItems: 'center' }}>
      <div style={{ width: '152px', marginRight: '8px' }}>
        <CEllipsis content={<span>{dataRef?.title}</span>} maxWidth={false} />
      </div>
      <Input
        size="small"
        style={{ height: '20px', width: '200px' }}
        value={dataRef?.newName}
        status={dataRef?.inputError ? 'error' : undefined}
        onChange={v => {
          onInputChange(dataRef?.key || '', v);
        }}
      />
    </div>
  );
};

export default () => {
  const [data, setData] = useState<TreeTransferDataType[]>(getInitDbTreeData().data);
  const [values, setValue] = useState<TreeTransferDataType[]>([]);
  const [loading, setLoading] = useState(false);

  const loadMore = async (parentKeys: (string | number)[], oldData: any[]) => {
    const cloneTree = cloneDeep(oldData);
    const nodeData = findItemByPath(parentKeys, cloneTree);

    const tableData = await getTablesDataByKey({
      tableNum: 10,
      instanceId: '',
      dbId: parentKeys[0],
      initCount: nodeData?.children?.length,
    });
    if (nodeData) {
      set(nodeData, 'children', [...tableData.data]);
      set(nodeData, 'hasMore', false);
    }
    return cloneTree;
  };

  const onSearch = async (searchStr: string, type: 'source' | 'target') => {
    if (type === 'source') {
      setLoading(true);
      const res = await getSearchData(searchStr);
      setData(res);
      setLoading(false);
    }
  };

  const onSourceLoadMore = async (parentKeys: string[]) => {
    const newData = (await loadMore(parentKeys, data)) || [];
    setData(newData);
  };
  const onTargetLoadMore = async (parentKeys: string[]) => {
    const newData = (await loadMore(parentKeys, values)) || [];
    setValue(newData);
  };

  const handleInputChange = (itemKey: string, newValue: string) => {
    const newData = values.map(item => {
      if (item.key === itemKey) {
        item.newName = newValue;
        // 可校验 input 内容是否有问题
        if (!newValue) {
          item.inputError = true;
        }
      }
      return item;
    });
    setValue(newData);
  };

  return (
    <>
      <CTreeTransfer
        arcoTransferProps={{
          listStyle: [
            { height: '480px', width: '300px' },
            { height: '480px', width: '500px' },
          ],
        }}
        hasLoadMore={true}
        treeData={data}
        targetTreeData={values}
        loading={loading}
        onChange={setValue}
        onSourceLoadMore={onSourceLoadMore}
        onTargetLoadMore={onTargetLoadMore}
        onSearch={onSearch}
        sourceSearchPlaceholder="搜索数据库"
        targetHeader={renderTargetHeader}
        targetItemRender={item => {
          return renderTargetItem({ item, onInputChange: handleInputChange });
        }}
      />
    </>
  );
};

